public Batch executeTask(Map<String,String> analysisProperties,Object... components){
  checkStarted();
  try {
    configureTaskLogging(analysisProperties);
  } catch (NullPointerException | IllegalStateException | IllegalArgumentException | ClassCastException e) {
    throw new RuntimeException("Error configuring task logging", e);
  }
  bootstrapContainer.executeTask(analysisProperties,components);
  configureLogging();
  return this;
}
